package com.projectseele.world;
import com.google.gson.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.zip.GZIPInputStream;import net.minecraft.world.phys.*;
/** Fourteen declared gates, actual affine motion sets against exact current native shapes. */
public final class VerifyCurrentGateWorldR53
{
 record Part(int index,String name,boolean moving,NervRigidMeshSweepR52 mesh){}
 record Step(int index,RigidTransform from,RigidTransform to,double start,double end,boolean moving){}
 record Cell(String key,JsonObject row,List<AABB> boxes){}
 static final Gson G=new GsonBuilder().setPrettyPrinting().create();
 static String sha(Path p)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}
 static RigidTransform frame(JsonArray a){return new RigidTransform(new Vec3(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble()),a.get(3).getAsFloat(),a.get(4).getAsFloat(),a.get(5).getAsFloat(),a.get(6).getAsFloat());}
 static AABB box(JsonArray a){return new AABB(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble(),a.get(3).getAsDouble(),a.get(4).getAsDouble(),a.get(5).getAsDouble());}
 static double[] values(AABB a){return new double[]{a.minX,a.minY,a.minZ,a.maxX,a.maxY,a.maxZ};}
 static boolean selected(String id){return id.matches("bay_[0-2]_(front|service_pit)")||id.matches("bank_[12]_rear_lane_[0-2]")||id.startsWith("remote_airshaft_");}
 public static void main(String[] args)throws Exception
 {
  Path input=Path.of(args[0]),out=Path.of(args[1]);Files.createDirectories(out);var doc=JsonParser.parseString(Files.readString(input)).getAsJsonObject();var profileParts=new HashMap<String,List<Part>>();var profileSteps=new HashMap<String,List<Step>>();
  for(var e:doc.getAsJsonObject("profiles").entrySet()){var profile=e.getValue().getAsJsonObject();Path mesh=input.getParent().resolve(profile.get("mesh_file").getAsString());if(!sha(mesh).equals(profile.get("mesh_sha256").getAsString()))throw new AssertionError("Typed source mesh changed");var parts=new ArrayList<Part>();try(var stream=new DataInputStream(new GZIPInputStream(Files.newInputStream(mesh)))){int count=stream.readInt();for(int i=0;i<count;i++){String name=stream.readUTF();boolean moving=stream.readBoolean();int n=stream.readInt();double[] xyz=new double[n/2];for(int k=0,t=0;k<n;k++){double v=stream.readDouble();if(k%6<3)xyz[t++]=v;}var declaration=profile.getAsJsonArray("parts").get(i).getAsJsonObject();if(!name.equals(i+"/"+declaration.get("name").getAsString())||moving!=declaration.get("moving").getAsBoolean())throw new AssertionError("Typed current source index mismatch");parts.add(new Part(i,name,moving,new NervRigidMeshSweepR52(xyz)));}}
   var steps=new ArrayList<Step>();var seen=new HashSet<String>();for(var raw:profile.getAsJsonArray("continuous_sweeps")){var j=raw.getAsJsonObject();if(j.get("extra_curve_error_m").getAsDouble()!=0||j.get("axis_count").getAsInt()>1)throw new AssertionError("Exact source monotone affine set required");int index=j.get("part").getAsInt();var a=frame(j.getAsJsonArray("from"));var b=frame(j.getAsJsonArray("to"));if(a.rotationErrorDegrees(b)>1e-6)throw new AssertionError("Source gate changed rotation");String key=index+"/"+a+"/"+b;if(seen.add(key))steps.add(new Step(index,a,b,j.get("progress_from").getAsDouble(),j.get("progress_to").getAsDouble(),j.get("moving").getAsBoolean()));}profileParts.put(e.getKey(),parts);profileSteps.put(e.getKey(),steps);}
  var candidates=args.length>2&&!args[2].equals("--envelopes")?JsonParser.parseString(Files.readString(Path.of(args[2]))).getAsJsonObject():null;var output=new ArrayList<Object>();int gates=0;
  for(var raw:doc.getAsJsonArray("gates")){var gate=raw.getAsJsonObject();String id=gate.get("resource").getAsString();if(args.length>3?!id.equals(args[3]):!selected(id))continue;gates++;String profile=gate.get("profile").getAsString();var root=frame(gate.getAsJsonArray("world_root"));var parts=profileParts.get(profile);var steps=profileSteps.get(profile);var envelopes=new LinkedHashMap<Integer,AABB>();for(var s:steps){var p=parts.get(s.index());envelopes.merge(s.index(),p.mesh().envelope(root.compose(s.from()),root.compose(s.to())),AABB::minmax);}
   if(candidates==null){var rows=new ArrayList<Object>();for(var e:envelopes.entrySet()){var p=parts.get(e.getKey());rows.add(Map.of("index",p.index(),"name",p.name(),"moving",p.moving(),"bounds",values(e.getValue())));}output.add(Map.of("resource",id,"parts",rows,"actual_bearing_contacts",gate.get("bearing_contacts"),"collision_steps",gate.get("collision_steps")));continue;}
   JsonObject measured=null;for(var value:candidates.getAsJsonArray("gates"))if(value.getAsJsonObject().get("resource").getAsString().equals(id))measured=value.getAsJsonObject();if(measured==null)throw new AssertionError("Exact current gate boxes absent");if(!measured.getAsJsonArray("unknown_shapes").isEmpty())throw new AssertionError("Unknown shape must hold "+id);
   var cells=new ArrayList<Cell>();for(var value:measured.getAsJsonArray("cells")){var j=value.getAsJsonObject();var p=j.getAsJsonArray("position");var boxes=new ArrayList<AABB>();for(var b:j.getAsJsonArray("native_boxes"))boxes.add(box(b.getAsJsonArray()));cells.add(new Cell(p.toString(),j,boxes));}var index=new NervStaticSpatialIndexR52<>(cells,c->{AABB b=null;for(var v:c.boxes())b=b==null?v:b.minmax(v);return b;});var hits=new LinkedHashMap<String,JsonObject>();long tests=0;
   for(var s:steps){var p=parts.get(s.index());var a=root.compose(s.from());var b=root.compose(s.to());for(var c:index.query(p.mesh().envelope(a,b))){if(c.row().get("own_dynamic_proxy").getAsBoolean())continue;boolean interior=false,boundary=false;for(var shape:c.boxes()){tests++;if(p.mesh().intersects(a,b,shape.deflate(2e-7),.003))interior=true;else if(p.mesh().intersects(a,b,shape,.003))boundary=true;}if(!interior&&!boundary)continue;String key=c.key()+"/"+p.index();var hit=hits.get(key);if(hit==null){hit=c.row().deepCopy();hit.addProperty("part",p.name());hit.addProperty("moving",p.moving());hit.add("actual_source_phase_intervals",new JsonArray());hit.addProperty("strict_interior_hit",false);hit.addProperty("boundary_only_hit",false);hits.put(key,hit);}hit.addProperty("strict_interior_hit",hit.get("strict_interior_hit").getAsBoolean()||interior);hit.addProperty("boundary_only_hit",hit.get("boundary_only_hit").getAsBoolean()||boundary);hit.getAsJsonArray("actual_source_phase_intervals").add(G.toJsonTree(new double[]{s.start(),s.end()}));}}
   output.add(Map.of("resource",id,"actual_unique_continuous_steps",steps.size(),"narrow_phase_tests",tests,"part_cell_hits",hits.values(),"block_entities",measured.get("block_entities")));System.out.println(id+" tests="+tests+" actual_part_cell_hits="+hits.size());Files.writeString(out.resolve("GATE14_WORLD_HITS_PARTIAL.json"),G.toJson(output));
  }
  if(gates!=(args.length>3?1:14))throw new AssertionError("Explicit current gate set required");var result=new LinkedHashMap<String,Object>();result.put("world_written",false);result.put("game_started",false);result.put("interface_sha256",sha(input));result.put("directory_sha256",doc.get("directory_sha256"));result.put("gates",output);if(candidates!=null){result.put("source_region_sha256",candidates.get("region_sha256"));result.put("native_shapes_sha256",candidates.get("native_shapes_sha256"));}result.put("scope","Actual current typed mesh, root-composed monotone one-axis whole motion sets, including fixed parts. Only this gate's own declared collision proxy is excluded as the same physical leaf; foreign dynamic proxies and declared bearing blocks remain measured and labelled. Strict native-box interior and boundary-only contact are separate. No World writes or native admission.");Files.writeString(out.resolve(candidates==null?"GATE14_CURRENT_ENVELOPES.json":"GATE14_CURRENT_WORLD_HITS.json"),G.toJson(result));
 }
}
